    [2943]={name="Eye of Paleth",quality=2,ilvl=31,reqLevel=22,sourceType="quest_reward",instructions="Reward from the quest 'Cleansing the Eye'. Starts with Glorin Steelbrow in Stormwind City. Objective: Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind.",zone="Wetlands",questName="Cleansing the Eye",lore="I can't lift the curse from the Eye of Paleth."},
    [2949]={name="Mariner Boots",quality=2,ilvl=25,reqLevel=20,sourceType="quest_reward",instructions="Reward from the quest 'Return the Statuette'. Pick it over the other reward choices. The quest is in Wetlands. Objective: Bring Karl Boran the Menethil Statuette.",zone="Wetlands",questName="Return the Statuette",lore="After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired Paladin with hammer upraised."},
