    [7738]={name="Evergreen Gloves",quality=2,ilvl=18,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Tharnariun's Hope'. Pick it over the other reward choices.",zone="Darkshore",questName="Tharnariun's Hope",lore="The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."},
