    [12062]={name="Skilled Fighting Blade",quality=3,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Jail Break!'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",zone="Blackrock Depths",questName="Jail Break!",lore="We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."},
    [12247]={name="Broad Bladed Knife",quality=2,ilvl=32,reqLevel=27,sourceType="vendor",instructions="Bought from Gavin Gnarltree in Stormwind (Alliance) or Ott in Orgrimmar (Horde).",zone="Hillsbrad Foothills",npc="Ott"},
