    [17743]={name="Resurgence Rod",quality=3,ilvl=53,reqLevel=45,sourceType="quest_reward",instructions="Reward from the quest 'Corruption of Earth and Seed'. Pick it over the other reward choices. Starts with Selendra in Maraudon. Objective: Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",zone="Maraudon",questName="Corruption of Earth and Seed",lore="Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship."},
