    [18807]={name="Helm of Latent Power",quality=3,ilvl=62,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'The Darkreaver Menace'. Starts with Sagorne Creststrider in Orgrimmar. Objective: Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",zone="Orgrimmar",questName="The Darkreaver Menace",lore="Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped!",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [18814]={name="Choker of the Fire Lord",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [18821]={name="Quick Strike Ring",quality=4,ilvl=67,reqLevel=60,sourceType="boss_drop",instructions="Drops from Garr.",zone="Molten Core",npc="Garr",lore="A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [18879]={name="Heavy Dark Iron Ring",quality=4,ilvl=66,reqLevel=60,sourceType="boss_drop",instructions="Drops from Gehennas.",zone="Molten Core",npc="Gehennas",lore="A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."},
