    [19371]={name="Pendant of the Fallen Dragon",quality=4,ilvl=74,reqLevel=60,sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [19376]={name="Archimtiros' Ring of Reckoning",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
