    [19808]={name="Rockhide Strongfish",quality=2,ilvl=45,reqLevel=40,sourceType="object_drop",instructions="Found in Wooden Chair.",npc="Wooden Chair"},
    [19828]={name="Zandalar Augur's Hauberk",quality=4,ilvl=65,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Augur's Hauberk'.",zone="Zul'Gurub",questName="Paragons of Power: The Augur's Hauberk",lore="The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [19829]={name="Zandalar Augur's Belt",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Augur's Belt'. Starts with Maywiki of Zuldazar in Stranglethorn Vale. Objective: Bring Maywiki of Zuldazar a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Augur's Belt",lore="Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"},
    [19830]={name="Zandalar Augur's Bracers",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Augur's Bracers'. Starts with Maywiki of Zuldazar in Stranglethorn Vale. Objective: Bring Maywiki of Zuldazar a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Augur's Bracers",lore="They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."},
    [19852]={name="Ancient Hakkari Manslayer",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for.",proc="Chance on hit: Steals 48 to 54 life from target enemy."},
    [19884]={name="Jin'do's Judgement",quality=4,ilvl=66,reqLevel=60,sourceType="boss_drop",instructions="Drops from Jin'do the Hexxer.",zone="Zul'Gurub",npc="Jin'do the Hexxer",lore="Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose.",proc="Equip: Improves your chance to hit by 2.0%."},
