    [20600]={name="Malfurion's Signet Ring",quality=4,ilvl=72,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Waking Legends'.",zone="Moonglade",questName="Waking Legends",lore="The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing."},
