    [21597]={name="Royal Scepter of Vek'lor",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other.",proc="Equip: Improves your chance to hit by 1.0%."},
