    [21624]={name="Gauntlets of Kalimdor",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Viscidus.",zone="Temple of Ahn'Qiraj",npc="Viscidus",lore="A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
